// WHITELIST — пропускаем дальше только сообщения от разрешённых chat_id.
// Чтобы добавить участника (например Михаила) — впиши его chat_id в массив
// ALLOWED. Узнать chat_id: пусть человек напишет /start боту @userinfobot.
const ALLOWED = ['264374209'];  // Алёна. Добавь сюда chat_id Михаила: ['264374209', 'XXXXX']

const msg = $input.first().json;
const chatId = String((msg && msg.message && msg.message.chat && msg.message.chat.id) || '');

if (ALLOWED.includes(chatId)) {
  return [{ json: msg }];
}
// Не в списке — workflow дальше не идёт, бот молчит.
return [];

// Парсер команды /goal:
//   /goal kcal=2190 protein=190 fat=70 carbs=200  → сохранить цель
//   /goal help                                     → справка
//   /goal                                          → подсказка
const text = ($('Конфиг').item.json.user_text || '').trim();
const chatId = $('Конфиг').item.json.chat_id;
const today = $('Конфиг').item.json.today_iso;

const stripped = text.replace(/^\/goal(@\w+)?\s*/i, '').trim();

if (/^help$/i.test(stripped)) {
  return [{ json: {
    action: 'reply_only', chat_id: chatId,
    reply_text: '🎯 *Цели КБЖУ*\n\n`/goal kcal=2190 protein=190 fat=70 carbs=200` — задать цель\n`/goal help` — эта справка\n\nДайджест и дашборд будут сравнивать твоё питание с этой целью.'
  }}];
}

if (!stripped) {
  return [{ json: {
    action: 'reply_only', chat_id: chatId,
    reply_text: '🎯 Текущая цель — на дашборде в блоке «Питание». Изменить:\n`/goal kcal=2190 protein=190 fat=70 carbs=200`'
  }}];
}

const args = {};
for (const pair of stripped.split(/\s+/)) {
  const m = pair.match(/^(\w+)=([\d.]+)$/);
  if (m) args[m[1].toLowerCase()] = parseFloat(m[2]);
}

const required = ['kcal', 'protein', 'fat', 'carbs'];
const missing = required.filter((k) => !isFinite(args[k]));
if (missing.length) {
  return [{ json: {
    action: 'reply_only', chat_id: chatId,
    reply_text: '⚠️ Не хватает полей: ' + missing.join(', ') + '\n\nПример: `/goal kcal=2190 protein=190 fat=70 carbs=200`'
  }}];
}

return [{ json: {
  action: 'add_goal', chat_id: chatId,
  reply_text: `✅ Цель сохранена:\n*${args.kcal} ккал · Б ${args.protein} / Ж ${args.fat} / У ${args.carbs}*\n\nДайджест начнёт сравнивать с этими числами.`,
  date_set: today, kcal: args.kcal, protein_g: args.protein, fat_g: args.fat, carbs_g: args.carbs, source: 'telegram'
}}];

// Дальше в Sheets — только если цель валидна (action=add_goal).
const item = $input.first().json;
if (item && item.action === 'add_goal' && item.kcal) {
  return [{ json: item }];
}
return [];

// Парсим JSON-ответ от Claude. Плоский объект — поля колонок на верхнем уровне.
const raw = $input.first().json;
let text = '';
try { text = raw.content[0].text || ''; } catch (e) { text = ''; }
text = text.replace(/```json\s*/i, '').replace(/```\s*$/, '').trim();

let parsed;
try { parsed = JSON.parse(text); }
catch (e) { parsed = { intent: 'unknown', _parse_error: text.slice(0, 200) }; }

const chatId = $('Конфиг').item.json.chat_id;

if (parsed.intent !== 'reminder' || !parsed.next_date || !parsed.title) {
  return [{ json: {
    action: 'reply_only', chat_id: chatId,
    reply_text: '🤔 Не понял как создать напоминание. Напиши в формате:\n\n• «30 мая — сдать анализы»\n• «через неделю — стоматолог»\n• «каждый понедельник — взвеситься»\n• «раз в 14 дней — стирать постельное»'
  }}];
}

const slug = parsed.title.toLowerCase().replace(/[^a-zа-яё0-9]+/gi, '-').replace(/-+/g, '-').replace(/^-|-$/g, '').slice(0, 30);
const reminderId = slug + '-' + Date.now().toString(36);

return [{ json: {
  action: 'add_reminder', chat_id: chatId,
  reply_text: `✅ Запомнила:\n*${parsed.title}*\nна *${parsed.next_date}* (${String(parsed.frequency || 'once')})`,
  reminder_id: reminderId,
  title: parsed.title,
  description: parsed.description || '',
  next_date: parsed.next_date,
  frequency: String(parsed.frequency || 'once'),
  enabled: 'TRUE',
  last_sent: ''
}}];

// Дальше в Sheets — только если action=add_reminder.
const item = $input.first().json;
if (item && item.action === 'add_reminder' && item.reminder_id) {
  return [{ json: item }];
}
return [];
